DO $$ DECLARE d text;anchor text;BEGIN d:=pg_get_functiondef('ops.apply_private_restore(uuid,bytea,uuid)'::regprocedure);anchor:='FROM %s t WHERE workspace_id=$1'',cols,name) INTO records USING scope_id;';IF strpos(d,anchor)=0 THEN RAISE EXCEPTION 'recovery exclusion anchor missing';END IF;d:=replace(d,anchor,'FROM %s t WHERE workspace_id=$1 %s'',cols,name,CASE WHEN name=''core.command_receipt'' THEN ''AND command_type<>''''portability.retire_notification'''''' ELSE '''' END) INTO records USING scope_id;');EXECUTE d;END $$;